update public.catalog_servicii set traduceri = jsonb_set(traduceri, '{en}', '{"titlu": "Aluminium transition profile for laminate flooring (installation included)", "domeniu": "Parquet & Flooring", "descriere": "Aluminium transition profile to bridge a difference in level or an expansion gap at the threshold between rooms — usual width 22-37mm, length 0.93-1.86m per piece, fixed or clipped onto the screed. Installation included in the price."}'::jsonb) where id = '391d3dba-0593-43c8-91ab-32d04bdd9430';
update public.catalog_servicii set traduceri = jsonb_set(traduceri, '{en}', '{"titlu": "Laminate flooring AC3 (7-8mm)", "domeniu": "Parquet & Flooring", "descriere": "Laminate flooring, wear class AC3 (EN 13329, residential use), usual thickness 7-8mm — suitable for bedrooms, living rooms and other normal-traffic areas. Click-lock system, floating installation, no adhesive."}'::jsonb) where id = '3de6a74e-f40d-462c-9a40-4c6c8f20c05b';
update public.catalog_servicii set traduceri = jsonb_set(traduceri, '{en}', '{"titlu": "Laminate flooring AC5 (10-12mm)", "domeniu": "Parquet & Flooring", "descriere": "Laminate flooring, wear class AC5 (EN 13329) — the most durable class available, suitable for heavy commercial traffic (public spaces, shops) or homes with very heavy use. Usual thickness 10-12mm, click-lock system, floating installation."}'::jsonb) where id = '14c4dda8-d630-445c-94b4-58333824690b';
update public.catalog_servicii set traduceri = jsonb_set(traduceri, '{en}', '{"titlu": "Flooring underlay 3mm", "domeniu": "Parquet & Flooring", "descriere": "Polyethylene foam underlay, 3 mm thick — reduces impact noise and evens out small irregularities in the screed under laminate flooring. For special layouts (e.g. herringbone), an underlay with a compressive strength of at least 150 kPa is recommended."}'::jsonb) where id = 'e03bc151-ebf2-4728-9c48-dc894ba7dbe2';
update public.catalog_servicii set traduceri = jsonb_set(traduceri, '{en}', '{"titlu": "Laminate flooring AC4 (8-10mm)", "domeniu": "Parquet & Flooring", "descriere": "Laminate flooring, wear class AC4 (EN 13329, heavy residential/light commercial use), usual thickness 8-10mm — suitable for hallways, offices and high-traffic living rooms. Click-lock system, floating installation; some versions in this class offer extra water resistance for humid areas."}'::jsonb) where id = 'd78556be-1259-4ab6-b0a6-f1119118906e';
update public.catalog_servicii set traduceri = jsonb_set(traduceri, '{en}', '{"titlu": "Laminate Flooring Installation", "domeniu": "Flooring & Parquet", "descriere": "Professional laminate flooring installation, carried out by a qualified tradesperson (category II floor fitter), according to the technical standard of 0.35 hours/m². The flooring (classes AC3–AC5), the underlay and the accessories (skirting, transition profile) are chosen separately, as optional materials, from the selector below or from the dedicated marketplace.", "etape_lucrare": ["Checking and preparing the screed (flatness, moisture, cleanliness)", "Laying the underlay over the whole area", "Laying the laminate flooring, with expansion gaps at the walls", "Fitting the accessories (skirting, transition profile), if ordered", "Final cleaning and handover of the work"], "instructiuni_intretinere": "Clean with a brush/vacuum cleaner or a slightly damp mop, without excess water. Avoid abrasive products and wax. Use felt pads under furniture to prevent scratches. Avoid prolonged exposure to direct sunlight and sudden changes in humidity, to prevent warping."}'::jsonb) where id = '59c4f00a-5438-4a70-9b6b-0fc142f243bc';
