-- Verificare
do $$
declare
  cu_en int;
begin
  select (select count(*) from public.catalog_servicii where status_public and traduceri ? 'en')
       + (select count(*) from public.catalog_niveluri where traduceri ? 'en')
       + (select count(*) from public.categorii where traduceri ? 'en')
    into cu_en;
  if cu_en < 942 then
    raise exception 'Doar % rânduri au traduceri.en (așteptat cel puțin 942)', cu_en;
  end if;
end $$;

